class Solution {
    public double average(int[] salary) {
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        long sum = 0;
        int count = 0;

        for (int s : salary) {
            if (s < min) {
                min = s;
            }
            if (s > max) {
                max = s;
            }
            sum += s;
            count++;
        }

        // Subtract min and max from the total sum
        sum -= (min + max);
        // Number of elements remaining after excluding min and max
        int n = count - 2;

        return (double) sum / n;
    }
}
